// Group items by recipe_ref AND storage location (derived from r1_path)
const getLocation = (r1Path) => {
  if (!r1Path) return 'unknown';
  if (r1Path.startsWith('/mnt/illuminastorage/')) return 'illuminastorage';
  if (r1Path.startsWith('/volume1/ALLDATA/')) return 'alldata';
  return 'other';
};

const grouped = {};
for (const item of $input.all()) {
  const recipeRef = item.json.recipe_ref;
  const location = getLocation(item.json.r1_path);
  const groupKey = `${recipeRef}__${location}`;

  if (!grouped[groupKey]) {
    grouped[groupKey] = {
      recipe_ref: recipeRef,
      location: location,
      items: []
    };
  }
  grouped[groupKey].items.push(item.json);
}

// Return as array of groups
return Object.values(grouped).map(group => ({
  json: {
    recipe_ref: group.recipe_ref,
    location: group.location,
    items: group.items,
    count: group.items.length
  }
}));

const stdout = $input.first().json.stdout;

if (!stdout) {
  throw new Error('stdout is empty');
}

let parsed;

try {
  parsed = JSON.parse(stdout);
} catch (e) {
  throw new Error('stdout is not valid JSON:\n' + stdout);
}

// Eğer array dönüyorsa → n8n item formatına çevir
if (Array.isArray(parsed)) {
  return parsed.map(item => ({ json: item }));
}

// Eğer object ise direkt dön
return [{ json: parsed }];

const stdout = $input.first().json.stdout || '';

// JSON kısmını yakala (object)
const match = stdout.match(/\{[\s\S]*\}$/);

if (!match) {
  throw new Error('JSON not found in stdout:\n' + stdout);
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (e) {
  throw new Error('Invalid JSON:\n' + match[0]);
}

// Genel başarı durumu
const jobSuccess = parsed.success;

// Sample bilgisi direkt yok → count var
// Ama senin önceki node’dan sample listesi geliyor olabilir
// Burada fallback olarak count kadar item üretelim

const samplesCount = parsed.samples_count || 0;

// Her sample için item üret
const items = [];

for (let i = 0; i < samplesCount; i++) {
  items.push({
    json: {
      job_id: parsed.job_id,
      job_name: parsed.job_name,
      success: jobSuccess,
      error: parsed.error,
      sample_index: i + 1,
      samples_count: samplesCount
    }
  });
}

return items;

// Priority list — earlier index = higher priority
const priorityOrder = ['143', '155', '213', '217'];

// Build a quick lookup: caresite_ref -> priority rank (lower = higher priority)
const priorityRank = new Map(priorityOrder.map((ref, idx) => [ref, idx]));

// Get the incoming groups (assumes each n8n item.json is one group object
// like { recipe_ref, location, items, count })
const groups = $input.all().map(i => i.json);

// Helper: find the best (lowest) priority rank among a group's items.
// If none of the items match a prioritized caresite, returns Infinity.
function getGroupPriority(group) {
  let best = Infinity;
  for (const item of group.items) {
    const ref = String(item.requesting_caresite_ref);
    if (priorityRank.has(ref)) {
      const rank = priorityRank.get(ref);
      if (rank < best) best = rank;
    }
  }
  return best;
}

// Attach priority, stable-sort, then strip the helper field back out
const sorted = groups
  .map((group, originalIndex) => ({
    group,
    originalIndex,
    priority: getGroupPriority(group)
  }))
  .sort((a, b) => {
    if (a.priority !== b.priority) return a.priority - b.priority;
    // tie-break: keep original relative order (stable sort)
    return a.originalIndex - b.originalIndex;
  })
  .map(x => x.group);

// Return as n8n items
return sorted.map(group => ({ json: group }));

const groups = $input.all().map(i => i.json);
const jsonStr = JSON.stringify(groups);
const b64 = Buffer.from(jsonStr).toString('base64');
return [{ json: { b64 } }];

const stdout = $input.first().json.stdout;
const parsed = JSON.parse(stdout);

return [{ json: parsed }];

const batchResult = $('Merge3').first().json;

const readRefs = [];
const statuses = [];

for (const batch of batchResult.batches) {
  for (const sample of batch.samples) {
    const item = batchResult.items.find(i => i.sample_id === sample.sample_id);
    if (!item) continue;
    readRefs.push(item.read_ref);
    statuses.push(sample.success && sample.failed_files === 0 ? 29 : 27);
  }
}

return [{
  json: {
    readRefsJson: JSON.stringify(readRefs),
    statusesJson: JSON.stringify(statuses)
  }
}];

